fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Given the input matrix with n rows and m columns,
    // return the j-th column as a vector of length n.
    // For each row i (0 <= i < n), take input[i][j].
    let mut col: Vec<i8> = Vec::with_capacity(n);
    for i in 0..n {
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // For each column j in 0..m, construct the column vector by collecting input[i][j] over all i.
    // This creates the transpose of the input matrix.
    let mut result: Vec<Vec<i8>> = Vec::with_capacity(m);
    for j in 0..m {
        let col = get_column(&input, j, m, n);
        result.push(col);
    }
    result
}